INSERT INTO public.certifications (slug,title,category,summary,skills,questions,question_count,pass_score,issuer_name)
VALUES ('demand-planning-sop', 'Demand Planning & S&OP', 'Supply Chain & Logistics', 'Run a monthly S&OP cycle that actually changes decisions.', ARRAY['Forecasting','S&OP','Cadence','Signals']::text[], '[{"q": "Days Inventory Outstanding (DIO) increasing usually means:", "options": ["Faster turns", "Slower turns / aging inventory", "Better margins", "Lower carrying cost"], "answer": 1}, {"q": "3PL vs 4PL: a 4PL primarily\u2026", "options": ["Owns trucks", "Orchestrates multiple 3PLs and the network", "Stores goods", "Handles customs only"], "answer": 1}, {"q": "Best mitigation for single-source supplier risk:", "options": ["Larger PO", "Qualify a second source", "Longer contract", "Tighter SLAs"], "answer": 1}, {"q": "Incoterm DDP places maximum responsibility on:", "options": ["Buyer", "Seller", "Carrier", "Insurer"], "answer": 1}, {"q": "Bullwhip effect is amplified by:", "options": ["Frequent small orders", "Demand signal distortion up the chain", "Vendor-managed inventory", "Real-time POS sharing"], "answer": 1}, {"q": "OTIF stands for:", "options": ["On Time In Full", "Order-To-Invoice-Flow", "Optimal Truck Inbound Flow", "Outbound Tariff Inbound Freight"], "answer": 0}, {"q": "Safety stock primarily protects against:", "options": ["Theft", "Demand and lead-time variability", "Tariffs", "FX risk"], "answer": 1}, {"q": "Economic Order Quantity (EOQ) balances:", "options": ["Lead time and demand", "Ordering and holding costs", "Tariffs and duties", "Freight and insurance"], "answer": 1}]'::jsonb, 8, 70, 'CERTIGO.')
