INSERT INTO public.certifications (slug,title,category,summary,skills,questions,question_count,pass_score,issuer_name)
VALUES ('product-management-foundations', 'Product Management Foundations', 'Product', 'Discover, prioritize, and ship products users love.', ARRAY['Discovery','RICE','Roadmap','Metrics']::text[], '[{"q": "North-star metric should be:", "options": ["Revenue only", "A leading indicator of customer value at scale", "Number of features shipped", "Headcount"], "answer": 1}, {"q": "Which is a ''vanity'' metric?", "options": ["Weekly active users with engagement filter", "Total page views", "Retention cohort", "D7 retention"], "answer": 1}, {"q": "A killed feature flag should be:", "options": ["Left in the code forever", "Removed once rollout is complete", "Renamed", "Documented and ignored"], "answer": 1}, {"q": "RICE prioritization ''C'' is:", "options": ["Cost", "Confidence", "Customer", "Complexity"], "answer": 1}, {"q": "Discovery interviews should mostly ask about:", "options": ["Future intent", "Past behavior", "Pricing willingness", "Roadmap opinions"], "answer": 1}, {"q": "Jobs-to-be-Done framing emphasizes:", "options": ["Personas", "The progress a user is trying to make", "Feature parity", "UI polish"], "answer": 1}, {"q": "A good PRD includes:", "options": ["UI screenshots only", "Problem, success metric, scope, non-goals", "Engineering estimates", "Marketing copy"], "answer": 1}, {"q": "Activation typically measures:", "options": ["First key moment of value", "Signups", "Revenue", "Retention curve"], "answer": 0}]'::jsonb, 8, 70, 'CERTIGO.')
