INSERT INTO public.certifications (slug,title,category,summary,skills,questions,question_count,pass_score,issuer_name)
VALUES ('prompt-engineering-essentials', 'Prompt Engineering Essentials', 'AI', 'Design prompts and guardrails for production LLM features.', ARRAY['Prompting','Eval','Guardrails','RAG']::text[], '[{"q": "Fine-tuning is preferred over prompting when:", "options": ["You need consistent stylistic behavior at scale", "You have one example", "Latency doesn''t matter", "Always"], "answer": 0}, {"q": "Temperature 0 yields:", "options": ["Maximum creativity", "More deterministic outputs", "Random outputs", "Faster inference"], "answer": 1}, {"q": "Embeddings are useful for:", "options": ["Storing raw text", "Semantic similarity search", "Compression only", "Encryption"], "answer": 1}, {"q": "Prompt injection mitigations include:", "options": ["Trusting all tool outputs", "Output validation and least-privilege tools", "Logging only", "Higher temperature"], "answer": 1}, {"q": "Few-shot prompting provides:", "options": ["Model weights", "Example input/output pairs in the prompt", "Fine-tune data", "System logs"], "answer": 1}, {"q": "A ''system'' message typically:", "options": ["Stores user history", "Sets assistant behavior and constraints", "Is ignored", "Returns tools"], "answer": 1}, {"q": "RAG stands for:", "options": ["Random Attention Gating", "Retrieval-Augmented Generation", "Recurrent Adaptive Grounding", "Reinforced Auto-Generation"], "answer": 1}, {"q": "LLM hallucinations are reduced most by:", "options": ["Higher temperature", "Grounding with retrieved context and citations", "Longer prompts only", "More tokens"], "answer": 1}]'::jsonb, 8, 70, 'CERTIGO.')
