VALUES ('data-literacy', 'Data Literacy', 'Data', 'Read data, avoid common pitfalls, and ask sharper questions.', ARRAY['Metrics','Stats','Visualization','Decisions']::text[], '[{"q": "Backfill in a data pipeline means:", "options": ["Deleting old data", "Reprocessing historical data", "Renaming columns", "Sharding"], "answer": 1}, {"q": "Cardinality of a ''country'' column is typically:", "options": ["Very high", "Low-to-medium", "Boolean", "Unique"], "answer": 1}, {"q": "PII columns should be:", "options": ["Stored in plaintext", "Tokenized or encrypted with access controls", "Public", "Cached aggressively"], "answer": 1}, {"q": "Median is preferred over mean when:", "options": ["Data is normal", "Data is skewed or has outliers", "Sample is large", "Always"], "answer": 1}, {"q": "Correlation vs causation: a strong correlation alone implies\u2026", "options": ["Causation", "Possible relationship, not cause", "Reverse causation", "Nothing"], "answer": 1}, {"q": "A p-value of 0.04 with alpha 0.05 means:", "options": ["Definite effect", "Statistically significant under that threshold", "No effect", "Bug in test"], "answer": 1}, {"q": "A good metric definition is:", "options": ["Stored only in dashboards", "Versioned in a semantic layer", "Recomputed ad hoc", "Decided per team"], "answer": 1}, {"q": "Star schema central table is the:", "options": ["Dimension", "Fact", "Bridge", "View"], "answer": 1}]'::jsonb, 8, 70, 'CERTIGO.')
